const shortcutURL=/Edg\//.test(shortcutAgent)?'edge://extensions/shortcuts':!/Firefox|Quark|QQBrowser|360|Qihoo|OPR\//i.test(shortcutAgent)&&/Chrome\//.test(shortcutAgent)?'chrome://extensions/shortcuts':null;
if(shortcutURL){
 const control=document.createElement('div');control.className='footer-shortcuts';
 const button=text('button','设置快捷键');button.type='button';button.className='shortcut-open';button.setAttribute('aria-describedby','shortcut-help');
 const refreshShortcut=async()=>{if(preview||!ext?.commands?.getAll)return;try{const commands=await ext.commands.getAll();const shortcut=commands.find(c=>c.name==='_execute_action')?.shortcut;button.textContent=shortcut?shortcut+' 唤起':'设置快捷键';button.title=shortcut?'按 '+shortcut+' 唤起拾隅，点击修改快捷键':'设置快捷键'}catch{}};void refreshShortcut();window.addEventListener('focus',refreshShortcut);document.addEventListener('visibilitychange',()=>{if(!document.hidden)void refreshShortcut()});
 const help=document.createElement('div');help.id='shortcut-help';help.className='shortcut-help';
 const message=text('p','复制下方地址，在新标签页的地址栏粘贴并打开，即可设置拾隅快捷键。');const address=text('code',shortcutURL);address.className='shortcut-address';const copy=document.createElement('button');copy.type='button';copy.className='shortcut-copy';copy.title='复制地址';copy.setAttribute('aria-label','复制快捷键设置地址');copy.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="8" y="8" width="12" height="12" rx="2"/><path d="M15 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h3"/></svg>';const addressRow=document.createElement('div');addressRow.className='shortcut-address-row';addressRow.append(address,copy);
 const feedback=text('span','');feedback.setAttribute('role','status');help.append(message,addressRow,feedback);control.append(button,help);$('.popup-footer').append(control);
 button.onclick=async()=>{try{if(preview)throw Error('preview');await api.call('open-shortcuts')}catch{control.classList.add('show-help');message.textContent='复制下方地址，在新标签页的地址栏粘贴并打开，即可设置拾隅快捷键。';copy.focus()}};
 copy.onclick=async()=>{try{await navigator.clipboard.writeText(shortcutURL);feedback.textContent='已复制'}catch{feedback.textContent='请选中地址后手动复制';const selection=getSelection(),range=document.createRange();range.selectNodeContents(address);selection.removeAllRanges();selection.addRange(range)}};
 document.addEventListener('pointerdown',e=>{if(!control.contains(e.target))control.classList.remove('show-help')});control.addEventListener('keydown',e=>{if(e.key==='Escape'){control.classList.remove('show-help');button.blur()}});
}

const updateNotice=document.createElement('button');updateNotice.type='button';updateNotice.className='extension-update-notice';updateNotice.hidden=true;$('.popup-footer').append(updateNotice);
let newerRelease=null;
async function openLatestExtension(){if(preview){window.open('https://shiyubox.com/extension/','_blank','noopener');return}try{await api.call('open-update')}catch{window.open('https://shiyubox.com/extension/','_blank','noopener')}}
function showRelease(release){newerRelease=release?.hasUpdate?release:null;updateNotice.hidden=!newerRelease;footerIdentity.classList.toggle('has-update',!!newerRelease);$('.popup-brand').href=newerRelease?'https://shiyubox.com/extension/':'https://shiyubox.com/';$('.popup-brand').setAttribute('aria-label',newerRelease?'下载新版拾隅插件':'打开拾隅主页');if(newerRelease){$('#version-status').textContent='V'+release.current;updateNotice.textContent='发现新版本 V'+release.latest+' · 点击下载';} }
